94	function prepareContent(entry: BatchEntry): PreparedEntry {
95	  const errors: string[] = [];
96	  const url = entry.url?.trim() || null;
97	
98	  // Apply UTM to body text first (in case there are inline agilepainrelief.com URLs)
99	  const linkedinWithUtm = addUtmParamsToText(entry.linkedin, "LinkedIn");
100	  const mastodonWithUtm = addUtmParamsToText(entry.mastodon, "Mastodon");
101	  const blueskyWithUtm = addUtmParamsToText(entry.bluesky, "Bluesky");
102	
103	  const linkedinHasInlineUrl = URL_TEST.test(linkedinWithUtm);
104	  const mastodonHasInlineUrl = URL_TEST.test(mastodonWithUtm);
105	  const blueskyHasInlineUrl = URL_TEST.test(blueskyWithUtm);
106	
107	  // Conflict check: url field AND inline URL in the same platform's body
108	  if (url) {
109	    if (linkedinHasInlineUrl) {
110	      errors.push(
111	        "LinkedIn body contains an inline URL AND `url` field is set — choose one",
112	      );
113	    }
114	    if (mastodonHasInlineUrl) {
115	      errors.push(
116	        "Mastodon body contains an inline URL AND `url` field is set — choose one",
117	      );
118	    }
119	    if (blueskyHasInlineUrl) {
120	      errors.push(
121	        "Bluesky body contains an inline URL AND `url` field is set — choose one",
122	      );
123	    }
124	  }
125	
126	  // Compose final post content. When the `url` field is set and a platform has
127	  // no inline URL, append the link to that platform's body. The link lives in
128	  // the body on every platform, LinkedIn included (no first comment).
129	  let linkedin = linkedinWithUtm;
130	  let mastodon = mastodonWithUtm;
131	  let bluesky = blueskyWithUtm;
132	
133	  if (url) {
134	    if (!linkedinHasInlineUrl) {
135	      linkedin = linkedin + "\n\n" + addUtmParamsToText(url, "LinkedIn");
136	    }
137	    if (!mastodonHasInlineUrl) {
138	      mastodon = mastodon + "\n\n" + addUtmParamsToText(url, "Mastodon");
139	    }
140	    if (!blueskyHasInlineUrl) {
141	      bluesky = bluesky + "\n\n" + addUtmParamsToText(url, "Bluesky");
142	    }
143	  }
144	
145	  return {
146	    content: {
147	      linkedin,
148	      mastodon: [mastodon],
149	      bluesky: [bluesky],
150	    },
151	    errors,
152	  };
153	}
154	
155	function resolveCoverImage(entry: BatchEntry): string | null {
156	  // Only use an image if one is explicitly provided in the JSON. We don't
157	  // auto-fetch og:image any more because Buffer's dedup matches shared
158	  // image assets across posts that point at the same source page.
159	  return entry.image && entry.image.trim() !== "" ? entry.image : null;
160	}
161	
162	// ============================================================================
163	// Pre-flight validation (hard halt on any error)
164	// ============================================================================
165	
166	function snippet(entry: BatchEntry): string {
167	  const text = entry.linkedin.replace(/\s+/g, " ").trim();
168	  return text.length > 30 ? text.slice(0, 30) + "…" : text;
169	}
