171	interface PreflightIssue {
172	  index: number;
173	  snippet: string;
174	  message: string;
175	}
176	
177	function preflight(entries: BatchEntry[]): PreflightIssue[] {
178	  const issues: PreflightIssue[] = [];
179	  for (const [i, entry] of entries.entries()) {
180	    const tag = snippet(entry);
181	    const { content, errors: prepErrors } = prepareContent(entry);
182	    for (const msg of prepErrors) {
183	      issues.push({ index: i + 1, snippet: tag, message: msg });
184	    }
185	    for (const err of validateCharacterLimits(content)) {
186	      issues.push({
187	        index: i + 1,
188	        snippet: tag,
189	        message: `${err.network} over ${err.limit} chars (got ${err.effectiveLength} after per-network URL counting)`,
190	      });
191	    }
192	    for (const msg of validateNoLinkInComments(content)) {
193	      issues.push({ index: i + 1, snippet: tag, message: msg });
194	    }
195	  }
196	  return issues;
197	}
198	
199	// ============================================================================
200	// Main
201	// ============================================================================
202	
203	interface CliArgs {
204	  file: string;
205	  dryRun: boolean;
206	  noProbe: boolean;
207	  occupied: string[];
208	}
209	
210	function parseArgs(): CliArgs {
211	  const args = process.argv.slice(2);
212	  const dryRun = args.includes("--dry-run");
213	  const noProbe = args.includes("--no-probe");
214	  const fileIdx = args.indexOf("--file");
215	  if (fileIdx === -1 || !args[fileIdx + 1]) {
216	    console.error(
217	      "Usage: npm run batch -- --file <path-to-json> [--dry-run] [--no-probe] [--occupied <iso> ...]",
218	    );
219	    process.exit(1);
220	  }
221	  const occupied: string[] = [];
222	  const occIdx = args.indexOf("--occupied");
223	  if (occIdx !== -1) {
224	    for (let i = occIdx + 1; i < args.length; i++) {
225	      if (args[i].startsWith("--")) break;
226	      occupied.push(args[i]);
227	    }
228	  }
229	  return { file: path.resolve(args[fileIdx + 1]), dryRun, noProbe, occupied };
230	}
231	
232	// ============================================================================
233	// Buffer probe — query scheduled posts so we know what slots are taken
234	// ============================================================================
235	
236	const ORG_QUERY = `query { account { organizations { id } } }`;
237	
238	const SCHEDULED_POSTS_QUERY = `
239	query ScheduledPosts(
240	  $organizationId: OrganizationId!,
241	  $channelIds: [ChannelId!]!
242	) {
243	  posts(
244	    input: {
245	      organizationId: $organizationId,
246	      filter: { channelIds: $channelIds, status: [scheduled] }
247	    },
248	    first: 100
249	  ) {
250	    edges {
251	      node {
252	        id
253	        dueAt
254	        status
255	        channelId
256	      }
257	    }
258	  }
259	}`;
260	
261	async function fetchOrganizationId(): Promise<string> {
262	  const result = await bufferApiQuery<{
263	    account?: { organizations?: Array<{ id: string }> };
264	  }>(ORG_QUERY);
265	  if (result.errors) {
266	    throw new Error(
267	      `Could not fetch organization id: ${result.errors.map((e) => e.message).join("; ")}`,
268	    );
269	  }
270	  const orgId = result.data?.account?.organizations?.[0]?.id;
271	  if (!orgId) throw new Error("No organization id on this Buffer account");
272	  return orgId;
273	}
274	
275	async function probeOccupiedSlots(): Promise<string[]> {
276	  const organizationId = await fetchOrganizationId();
277	  const channelIds = (
278	    ["LinkedIn", "Mastodon", "Bluesky"] as NetworkType[]
279	  ).map((n) => CHANNEL_IDS[n]);
280	
281	  const result = await bufferApiQuery<{
282	    posts?: {
283	      edges?: Array<{
284	        node?: { dueAt?: string; channelId?: string };
285	      }>;
286	    };
287	  }>(SCHEDULED_POSTS_QUERY, { organizationId, channelIds });
288	
289	  if (result.errors) {
290	    throw new Error(
291	      `Buffer probe failed: ${result.errors.map((e) => e.message).join("; ")}`,
292	    );
293	  }
294	
295	  const edges = result.data?.posts?.edges || [];
296	  const byChannel: Record<string, string[]> = {};
297	  for (const edge of edges) {
298	    const dueAt = edge.node?.dueAt;
299	    const channelId = edge.node?.channelId;
300	    if (!dueAt || !channelId) continue;
301	    (byChannel[channelId] ||= []).push(dueAt);
302	  }
303	  for (const [network, channelId] of Object.entries(CHANNEL_IDS)) {
304	    console.log(`  ${network}: ${(byChannel[channelId] || []).length} scheduled post(s)`);
305	  }
306	  return edges
307	    .map((e) => e.node?.dueAt)
308	    .filter((d): d is string => typeof d === "string");
309	}
310	
311	// Thrown when Buffer rejects a per-post create (e.g. duplicate detection,
312	// content policy). Distinct from systemic errors (network, auth, GraphQL)
313	// which still abort the batch.
314	class BufferRejectionError extends Error {
315	  constructor(
316	    public network: string,
317	    public bufferMessage: string,
318	  ) {
319	    super(`${network} createPost failed: ${bufferMessage}`);
320	  }
321	}
322	
323	async function scheduleOne(
324	  entry: BatchEntry,
325	  index: number,
326	  dueAt: string,
327	  dryRun: boolean,
328	): Promise<void> {
329	  const { content } = prepareContent(entry);
330	  const coverImageUrl = resolveCoverImage(entry);
331	
332	  const mode = "customScheduled" as const;
333	  const inputs: [string, CreatePostInput][] = [
334	    [
335	      "LinkedIn",
336	      { ...buildLinkedInInput(content, coverImageUrl, mode), dueAt },
337	    ],
338	    [
339	      "Mastodon",
340	      { ...buildMastodonInput(content, coverImageUrl, mode), dueAt },
341	    ],
342	    ["Bluesky", { ...buildBlueskyInput(content, coverImageUrl, mode), dueAt }],
343	  ];
344	
345	  if (dryRun) {
346	    console.log(`  [post ${index + 1}] dry-run payloads for ${dueAt}:`);
347	    for (const [name, input] of inputs) {
348	      console.log(`    --- ${name} ---`);
349	      console.log(JSON.stringify(input, null, 2).replace(/^/gm, "    "));
350	    }
351	    return;
352	  }
353	
354	  for (const [name, input] of inputs) {
355	    const result = await bufferApiQuery(CREATE_POST_MUTATION, { input });
356	
357	    if (result.errors) {
358	      const messages = result.errors.map((e) => e.message).join("; ");
359	      throw new Error(`${name} GraphQL error: ${messages}`);
360	    }
361	
362	    const data = result.data as {
363	      createPost:
364	        | { post: { id: string; text: string; status: string; dueAt: string } }
365	        | { message: string };
366	    };
367	
368	    if ("message" in data.createPost) {
369	      throw new BufferRejectionError(name, data.createPost.message);
370	    }
371	    console.log(
372	      `  [post ${index + 1}] ${name} scheduled (id: ${data.createPost.post.id}) for ${dueAt}`,
373	    );
374	  }
375	}
376	
377	async function main(): Promise<void> {
378	  const { file, dryRun, noProbe, occupied } = parseArgs();
379	  loadEnv();
380	
381	  console.log(`Reading batch file: ${file}`);
382	  const entries = readBatchFile(file);
383	  console.log(`Loaded ${entries.length} post(s).`);
384	
385	  console.log("\nPre-flighting entries...");
386	  const issues = preflight(entries);
387	  if (issues.length > 0) {
388	    console.error(`\n${issues.length} validation error(s). NOT posting:`);
389	    for (const issue of issues) {
390	      console.error(
391	        `  • post ${issue.index} ("${issue.snippet}") — ${issue.message}`,
392	      );
393	    }
394	    console.error("\nFix the JSON file and re-run.");
395	    process.exit(1);
396	  }
397	  console.log("  All entries passed pre-flight.");
398	
399	  let probedSlots: string[] = [];
400	  if (!noProbe) {
401	    console.log("\nProbing Buffer for scheduled posts...");
402	    probedSlots = await probeOccupiedSlots();
403	    console.log(`  Total occupied slots discovered: ${probedSlots.length}`);
404	  } else {
405	    console.log("\nSkipping Buffer probe (--no-probe).");
406	  }
407	
408	  const state = readScheduleState();
409	  const sessionSlots: string[] = [];
410	  // State file is kept as a cache but Buffer's probe is the source of truth.
411	  // Manual --occupied overrides are also merged in.
412	  const baselineUsed = noProbe
413	    ? [...state.scheduledSlots, ...occupied]
414	    : [...probedSlots, ...occupied];
415	  const skipped: Array<{ index: number; reason: string; snippet: string }> = [];
416	
417	  console.log("\n" + "=".repeat(60));
418	  console.log(
419	    dryRun
420	      ? "DRY RUN — Computing slots and previewing payloads"
421	      : "Scheduling posts via Buffer API",
422	  );
423	  console.log("=".repeat(60));
424	
425	  for (const [i, entry] of entries.entries()) {
426	    const usedSlots = [...baselineUsed, ...sessionSlots];
427	    const dueAt = findNextSlot(new Date(), usedSlots);
428	    console.log(`\nPost ${i + 1}/${entries.length} → ${dueAt}`);
429	
430	    try {
431	      await scheduleOne(entry, i, dueAt, dryRun);
432	    } catch (err) {
433	      if (err instanceof BufferRejectionError) {
434	        const tag = snippet(entry);
435	        console.error(
436	          `  SKIPPED post ${i + 1} ("${tag}") — ${err.network}: ${err.bufferMessage}`,
437	        );
438	        skipped.push({ index: i + 1, reason: err.message, snippet: tag });
439	        // Slot was attempted; some platforms may have succeeded before the
440	        // rejection. Mark it consumed so the next post moves to a fresh slot.
441	        sessionSlots.push(dueAt);
442	        if (!dryRun) {
443	          state.scheduledSlots.push(dueAt);
444	          writeScheduleState(state);
445	        }
446	        continue;
447	      }
448	      console.error(`\nFAILED on post ${i + 1}: ${err}`);
449	      console.error(
450	        `Stopping. ${i - skipped.length} post(s) scheduled, ${skipped.length} skipped, ${entries.length - i} remaining.`,
451	      );
452	      if (!dryRun && sessionSlots.length > 0) {
453	        state.scheduledSlots.push(...sessionSlots);
454	        writeScheduleState(state);
455	        console.error(
456	          `State file updated with ${sessionSlots.length} slot(s) used in this session.`,
457	        );
458	      }
459	      process.exit(1);
460	    }
461	
462	    sessionSlots.push(dueAt);
463	
464	    if (!dryRun) {
465	      state.scheduledSlots.push(dueAt);
466	      writeScheduleState(state);
467	    }
468	  }
469	
470	  console.log("\n" + "=".repeat(60));
471	  const succeeded = entries.length - skipped.length;
472	  if (dryRun) {
473	    console.log(`Dry run complete. ${entries.length} slot(s) computed, nothing posted.`);
474	  } else {
475	    console.log(`Batch complete. ${succeeded} scheduled, ${skipped.length} skipped.`);
476	  }
477	  if (skipped.length > 0) {
478	    console.log("\nSkipped posts (Buffer rejected, batch continued):");
479	    for (const s of skipped) {
480	      console.log(`  • post ${s.index} ("${s.snippet}") — ${s.reason}`);
481	    }
482	  }
483	  console.log("=".repeat(60));
484	}
485	
486	if (import.meta.url === `file://${process.argv[1]}`) {
487	  main().catch((err) => {
488	    console.error(err);
489	    process.exit(1);
490	  });
491	}
