import * as fs from "fs";
import * as path from "path";
import {
  loadEnv,
  bufferApiQuery,
  CREATE_POST_MUTATION,
  CHANNEL_IDS,
  buildLinkedInInput,
  buildMastodonInput,
  buildBlueskyInput,
  validateCharacterLimits,
  validateNoLinkInComments,
  addUtmParamsToText,
  PostContent,
  CreatePostInput,
  NetworkType,
} from "./bufferPost";
import { findNextSlot } from "./slotAllocator";

// ============================================================================
// Batch Input
// ============================================================================

interface BatchEntry {
  linkedin: string;
  mastodon: string;
  bluesky: string;
  url?: string;
  image?: string;
}

interface ScheduleState {
  scheduledSlots: string[];
}

const EVERGREEN_DIR = path.resolve("analytics/social-media-content-evergreen");
const STATE_FILE = path.join(EVERGREEN_DIR, ".schedule-state.json");

function readBatchFile(filePath: string): BatchEntry[] {
  if (!fs.existsSync(filePath)) {
    console.error(`Batch file not found: ${filePath}`);
    process.exit(1);
  }
  const raw = fs.readFileSync(filePath, "utf-8");
  const data = JSON.parse(raw);
  if (!Array.isArray(data)) {
    console.error(`Batch file must contain a JSON array, got ${typeof data}`);
    process.exit(1);
  }
  for (const [i, entry] of data.entries()) {
    if (
      typeof entry.linkedin !== "string" ||
      typeof entry.mastodon !== "string" ||
      typeof entry.bluesky !== "string"
    ) {
      console.error(
        `Entry ${i + 1} missing required fields (linkedin, mastodon, bluesky)`,
      );
      process.exit(1);
    }
  }
  return data;
}

function readScheduleState(): ScheduleState {
  if (!fs.existsSync(STATE_FILE)) {
    return { scheduledSlots: [] };
  }
  return JSON.parse(fs.readFileSync(STATE_FILE, "utf-8")) as ScheduleState;
}

function writeScheduleState(state: ScheduleState): void {
  if (!fs.existsSync(EVERGREEN_DIR)) {
    fs.mkdirSync(EVERGREEN_DIR, { recursive: true });
  }
  fs.writeFileSync(
    STATE_FILE,
    JSON.stringify(state, null, 2) + "\n",
    "utf-8",
  );
}

// ============================================================================
// Per-entry preparation
// ============================================================================

const URL_TEST = /https?:\/\//;

interface PreparedEntry {
  content: PostContent;
  errors: string[];
}

function prepareContent(entry: BatchEntry): PreparedEntry {
  const errors: string[] = [];
  const url = entry.url?.trim() || null;

  // Apply UTM to body text first (in case there are inline agilepainrelief.com URLs)
  const linkedinWithUtm = addUtmParamsToText(entry.linkedin, "LinkedIn");
  const mastodonWithUtm = addUtmParamsToText(entry.mastodon, "Mastodon");
  const blueskyWithUtm = addUtmParamsToText(entry.bluesky, "Bluesky");

  const linkedinHasInlineUrl = URL_TEST.test(linkedinWithUtm);
  const mastodonHasInlineUrl = URL_TEST.test(mastodonWithUtm);
  const blueskyHasInlineUrl = URL_TEST.test(blueskyWithUtm);

  // Conflict check: url field AND inline URL in the same platform's body
  if (url) {
    if (linkedinHasInlineUrl) {
      errors.push(
        "LinkedIn body contains an inline URL AND `url` field is set — choose one",
      );
    }
    if (mastodonHasInlineUrl) {
      errors.push(
        "Mastodon body contains an inline URL AND `url` field is set — choose one",
      );
    }
    if (blueskyHasInlineUrl) {
      errors.push(
        "Bluesky body contains an inline URL AND `url` field is set — choose one",
      );
    }
  }

  // Compose final post content. When the `url` field is set and a platform has
  // no inline URL, append the link to that platform's body. The link lives in
  // the body on every platform, LinkedIn included (no first comment).
  let linkedin = linkedinWithUtm;
  let mastodon = mastodonWithUtm;
  let bluesky = blueskyWithUtm;

  if (url) {
    if (!linkedinHasInlineUrl) {
      linkedin = linkedin + "\n\n" + addUtmParamsToText(url, "LinkedIn");
    }
    if (!mastodonHasInlineUrl) {
      mastodon = mastodon + "\n\n" + addUtmParamsToText(url, "Mastodon");
    }
    if (!blueskyHasInlineUrl) {
      bluesky = bluesky + "\n\n" + addUtmParamsToText(url, "Bluesky");
    }
  }

  return {
    content: {
      linkedin,
      mastodon: [mastodon],
      bluesky: [bluesky],
    },
    errors,
  };
}

function resolveCoverImage(entry: BatchEntry): string | null {
  // Only use an image if one is explicitly provided in the JSON. We don't
  // auto-fetch og:image any more because Buffer's dedup matches shared
  // image assets across posts that point at the same source page.
  return entry.image && entry.image.trim() !== "" ? entry.image : null;
}

// ============================================================================
// Pre-flight validation (hard halt on any error)
// ============================================================================

function snippet(entry: BatchEntry): string {
  const text = entry.linkedin.replace(/\s+/g, " ").trim();
  return text.length > 30 ? text.slice(0, 30) + "…" : text;
}

interface PreflightIssue {
  index: number;
  snippet: string;
  message: string;
}

function preflight(entries: BatchEntry[]): PreflightIssue[] {
  const issues: PreflightIssue[] = [];
  for (const [i, entry] of entries.entries()) {
    const tag = snippet(entry);
    const { content, errors: prepErrors } = prepareContent(entry);
    for (const msg of prepErrors) {
      issues.push({ index: i + 1, snippet: tag, message: msg });
    }
    for (const err of validateCharacterLimits(content)) {
      issues.push({
        index: i + 1,
        snippet: tag,
        message: `${err.network} over ${err.limit} chars (got ${err.effectiveLength} after per-network URL counting)`,
      });
    }
    for (const msg of validateNoLinkInComments(content)) {
      issues.push({ index: i + 1, snippet: tag, message: msg });
    }
  }
  return issues;
}

// ============================================================================
// Main
// ============================================================================

interface CliArgs {
  file: string;
  dryRun: boolean;
  noProbe: boolean;
  occupied: string[];
}

function parseArgs(): CliArgs {
  const args = process.argv.slice(2);
  const dryRun = args.includes("--dry-run");
  const noProbe = args.includes("--no-probe");
  const fileIdx = args.indexOf("--file");
  if (fileIdx === -1 || !args[fileIdx + 1]) {
    console.error(
      "Usage: npm run batch -- --file <path-to-json> [--dry-run] [--no-probe] [--occupied <iso> ...]",
    );
    process.exit(1);
  }
  const occupied: string[] = [];
  const occIdx = args.indexOf("--occupied");
  if (occIdx !== -1) {
    for (let i = occIdx + 1; i < args.length; i++) {
      if (args[i].startsWith("--")) break;
      occupied.push(args[i]);
    }
  }
  return { file: path.resolve(args[fileIdx + 1]), dryRun, noProbe, occupied };
}

// ============================================================================
// Buffer probe — query scheduled posts so we know what slots are taken
// ============================================================================

const ORG_QUERY = `query { account { organizations { id } } }`;

const SCHEDULED_POSTS_QUERY = `
query ScheduledPosts(
  $organizationId: OrganizationId!,
  $channelIds: [ChannelId!]!
) {
  posts(
    input: {
      organizationId: $organizationId,
      filter: { channelIds: $channelIds, status: [scheduled] }
    },
    first: 100
  ) {
    edges {
      node {
        id
        dueAt
        status
        channelId
      }
    }
  }
}`;

async function fetchOrganizationId(): Promise<string> {
  const result = await bufferApiQuery<{
    account?: { organizations?: Array<{ id: string }> };
  }>(ORG_QUERY);
  if (result.errors) {
    throw new Error(
      `Could not fetch organization id: ${result.errors.map((e) => e.message).join("; ")}`,
    );
  }
  const orgId = result.data?.account?.organizations?.[0]?.id;
  if (!orgId) throw new Error("No organization id on this Buffer account");
  return orgId;
}

async function probeOccupiedSlots(): Promise<string[]> {
  const organizationId = await fetchOrganizationId();
  const channelIds = (
    ["LinkedIn", "Mastodon", "Bluesky"] as NetworkType[]
  ).map((n) => CHANNEL_IDS[n]);

  const result = await bufferApiQuery<{
    posts?: {
      edges?: Array<{
        node?: { dueAt?: string; channelId?: string };
      }>;
    };
  }>(SCHEDULED_POSTS_QUERY, { organizationId, channelIds });

  if (result.errors) {
    throw new Error(
      `Buffer probe failed: ${result.errors.map((e) => e.message).join("; ")}`,
    );
  }

  const edges = result.data?.posts?.edges || [];
  const byChannel: Record<string, string[]> = {};
  for (const edge of edges) {
    const dueAt = edge.node?.dueAt;
    const channelId = edge.node?.channelId;
    if (!dueAt || !channelId) continue;
    (byChannel[channelId] ||= []).push(dueAt);
  }
  for (const [network, channelId] of Object.entries(CHANNEL_IDS)) {
    console.log(`  ${network}: ${(byChannel[channelId] || []).length} scheduled post(s)`);
  }
  return edges
    .map((e) => e.node?.dueAt)
    .filter((d): d is string => typeof d === "string");
}

// Thrown when Buffer rejects a per-post create (e.g. duplicate detection,
// content policy). Distinct from systemic errors (network, auth, GraphQL)
// which still abort the batch.
class BufferRejectionError extends Error {
  constructor(
    public network: string,
    public bufferMessage: string,
  ) {
    super(`${network} createPost failed: ${bufferMessage}`);
  }
}

async function scheduleOne(
  entry: BatchEntry,
  index: number,
  dueAt: string,
  dryRun: boolean,
): Promise<void> {
  const { content } = prepareContent(entry);
  const coverImageUrl = resolveCoverImage(entry);

  const mode = "customScheduled" as const;
  const inputs: [string, CreatePostInput][] = [
    [
      "LinkedIn",
      { ...buildLinkedInInput(content, coverImageUrl, mode), dueAt },
    ],
    [
      "Mastodon",
      { ...buildMastodonInput(content, coverImageUrl, mode), dueAt },
    ],
    ["Bluesky", { ...buildBlueskyInput(content, coverImageUrl, mode), dueAt }],
  ];

  if (dryRun) {
    console.log(`  [post ${index + 1}] dry-run payloads for ${dueAt}:`);
    for (const [name, input] of inputs) {
      console.log(`    --- ${name} ---`);
      console.log(JSON.stringify(input, null, 2).replace(/^/gm, "    "));
    }
    return;
  }

  for (const [name, input] of inputs) {
    const result = await bufferApiQuery(CREATE_POST_MUTATION, { input });

    if (result.errors) {
      const messages = result.errors.map((e) => e.message).join("; ");
      throw new Error(`${name} GraphQL error: ${messages}`);
    }

    const data = result.data as {
      createPost:
        | { post: { id: string; text: string; status: string; dueAt: string } }
        | { message: string };
    };

    if ("message" in data.createPost) {
      throw new BufferRejectionError(name, data.createPost.message);
    }
    console.log(
      `  [post ${index + 1}] ${name} scheduled (id: ${data.createPost.post.id}) for ${dueAt}`,
    );
  }
}

async function main(): Promise<void> {
  const { file, dryRun, noProbe, occupied } = parseArgs();
  loadEnv();

  console.log(`Reading batch file: ${file}`);
  const entries = readBatchFile(file);
  console.log(`Loaded ${entries.length} post(s).`);

  console.log("\nPre-flighting entries...");
  const issues = preflight(entries);
  if (issues.length > 0) {
    console.error(`\n${issues.length} validation error(s). NOT posting:`);
    for (const issue of issues) {
      console.error(
        `  • post ${issue.index} ("${issue.snippet}") — ${issue.message}`,
      );
    }
    console.error("\nFix the JSON file and re-run.");
    process.exit(1);
  }
  console.log("  All entries passed pre-flight.");

  let probedSlots: string[] = [];
  if (!noProbe) {
    console.log("\nProbing Buffer for scheduled posts...");
    probedSlots = await probeOccupiedSlots();
    console.log(`  Total occupied slots discovered: ${probedSlots.length}`);
  } else {
    console.log("\nSkipping Buffer probe (--no-probe).");
  }

  const state = readScheduleState();
  const sessionSlots: string[] = [];
  // State file is kept as a cache but Buffer's probe is the source of truth.
  // Manual --occupied overrides are also merged in.
  const baselineUsed = noProbe
    ? [...state.scheduledSlots, ...occupied]
    : [...probedSlots, ...occupied];
  const skipped: Array<{ index: number; reason: string; snippet: string }> = [];

  console.log("\n" + "=".repeat(60));
  console.log(
    dryRun
      ? "DRY RUN — Computing slots and previewing payloads"
      : "Scheduling posts via Buffer API",
  );
  console.log("=".repeat(60));

  for (const [i, entry] of entries.entries()) {
    const usedSlots = [...baselineUsed, ...sessionSlots];
    const dueAt = findNextSlot(new Date(), usedSlots);
    console.log(`\nPost ${i + 1}/${entries.length} → ${dueAt}`);

    try {
      await scheduleOne(entry, i, dueAt, dryRun);
    } catch (err) {
      if (err instanceof BufferRejectionError) {
        const tag = snippet(entry);
        console.error(
          `  SKIPPED post ${i + 1} ("${tag}") — ${err.network}: ${err.bufferMessage}`,
        );
        skipped.push({ index: i + 1, reason: err.message, snippet: tag });
        // Slot was attempted; some platforms may have succeeded before the
        // rejection. Mark it consumed so the next post moves to a fresh slot.
        sessionSlots.push(dueAt);
        if (!dryRun) {
          state.scheduledSlots.push(dueAt);
          writeScheduleState(state);
        }
        continue;
      }
      console.error(`\nFAILED on post ${i + 1}: ${err}`);
      console.error(
        `Stopping. ${i - skipped.length} post(s) scheduled, ${skipped.length} skipped, ${entries.length - i} remaining.`,
      );
      if (!dryRun && sessionSlots.length > 0) {
        state.scheduledSlots.push(...sessionSlots);
        writeScheduleState(state);
        console.error(
          `State file updated with ${sessionSlots.length} slot(s) used in this session.`,
        );
      }
      process.exit(1);
    }

    sessionSlots.push(dueAt);

    if (!dryRun) {
      state.scheduledSlots.push(dueAt);
      writeScheduleState(state);
    }
  }

  console.log("\n" + "=".repeat(60));
  const succeeded = entries.length - skipped.length;
  if (dryRun) {
    console.log(`Dry run complete. ${entries.length} slot(s) computed, nothing posted.`);
  } else {
    console.log(`Batch complete. ${succeeded} scheduled, ${skipped.length} skipped.`);
  }
  if (skipped.length > 0) {
    console.log("\nSkipped posts (Buffer rejected, batch continued):");
    for (const s of skipped) {
      console.log(`  • post ${s.index} ("${s.snippet}") — ${s.reason}`);
    }
  }
  console.log("=".repeat(60));
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}

