300	      errors.push(`Mastodon part ${i + 1} contains "link in the comments"`);
301	    }
302	  }
303	  for (const [i, part] of content.bluesky.entries()) {
304	    if (LINK_IN_COMMENTS_REGEX.test(part)) {
305	      errors.push(`Bluesky part ${i + 1} contains "link in the comments"`);
306	    }
