331	    const effectiveLength = calculateEffectiveLength(
332	      part,
333	      URL_COUNT_LENGTH.Mastodon,
334	    );
335	    if (effectiveLength > CHAR_LIMITS.Mastodon) {
336	      errors.push({
337	        network: "Mastodon",
338	        partIndex: index + 1,
339	        content: part,
