391	// ============================================================================
392	// LinkedIn Link Extraction
393	// ============================================================================
394	
395	/**
396	 * Extract all URLs from LinkedIn content.
397	 * Returns an empty array if no URLs are found.
398	 */
399	function extractLinks(text: string): string[] {
400	  return text.match(URL_REGEX) || [];
401	}
