403	// ============================================================================
404	// UTM Parameter Handling
405	// ============================================================================
406	
407	const AGILEPAINRELIEF_REGEX = /https?:\/\/agilepainrelief\.com[^\s)"]*/gi;
408	const UTM_PARAMS: Record<NetworkType, string> = {
409	  LinkedIn: "?utm_source=linkedin&utm_campaign=archive-reshare",
410	  Mastodon: "?utm_source=mastodon&utm_campaign=archive-reshare",
411	  Bluesky: "?utm_source=bluesky&utm_campaign=archive-reshare",
412	};
413	
414	/**
415	 * Add UTM parameters to agilepainrelief.com URLs that don't already have utm params.
416	 * Preserves existing query strings by appending with & instead of ?.
417	 */
418	function addUtmToUrl(url: string, utmParams: string): string {
419	  // Check if URL already has utm parameters
420	  if (url.includes("utm_")) {
421	    return url;
422	  }
423	
424	  // Check if URL already has query parameters
425	  if (url.includes("?")) {
426	    // Append UTM params with & (remove leading ? from utmParams)
427	    return url + "&" + utmParams.substring(1);
428	  }
429	
430	  // No existing query params, add UTM with ?
431	  return url + utmParams;
432	}
433	
434	/**
435	 * Add UTM parameters to all agilepainrelief.com URLs in text for a specific platform.
436	 */
437	export function addUtmParamsToText(
438	  text: string,
439	  platform: NetworkType,
440	): string {
441	  const utmParams = UTM_PARAMS[platform];
442	  return text.replace(AGILEPAINRELIEF_REGEX, (url) =>
443	    addUtmToUrl(url, utmParams),
444	  );
445	}
446	
447	/**
448	 * Add UTM parameters to all parts of content for a specific platform.
449	 */
450	export function addUtmParamsToParts(
451	  parts: string[],
452	  platform: NetworkType,
453	): string[] {
454	  return parts.map((part) => addUtmParamsToText(part, platform));
455	}
456	
457	// ============================================================================
458	// Cover Image Extraction
459	// ============================================================================
460	
461	/**
462	 * Extract the blog URL from LinkedIn content.
463	 * Looks for agilepainrelief.com URLs.
464	 */
465	function extractBlogUrl(content: string): string | null {
466	  const match = content.match(AGILEPAINRELIEF_REGEX);
467	  return match ? match[0] : null;
468	}
469	
470	/**
471	 * Fetch a blog page and extract the og:image URL from its meta tags.
472	 */
473	export async function fetchCoverImageUrl(
474	  blogUrl: string,
475	): Promise<string | null> {
476	  const response = await fetch(blogUrl);
477	  if (!response.ok) {
478	    console.log(
479	      `Warning: Failed to fetch blog page (${response.status}): ${blogUrl}`,
480	    );
481	    return null;
482	  }
483	
484	  const html = await response.text();
485	
486	  // Match og:image meta tag (handles both attribute orderings)
487	  const ogImageMatch =
488	    html.match(
489	      /<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']*)["']/,
490	    ) ||
491	    html.match(
492	      /<meta[^>]*content=["']([^"']*)["'][^>]*property=["']og:image["']/,
493	    );
494	
495	  if (!ogImageMatch) {
496	    console.log("Warning: No og:image meta tag found on blog page.");
497	    return null;
498	  }
499	
500	  return ogImageMatch[1];
501	}
502	
503	/**
504	 * Extract the cover image URL from the blog post linked in the content.
505	 * Returns the og:image URL, or null if no image found.
506	 * Never throws — logs warnings and returns null on failure.
507	 */
508	async function fetchCoverImage(
509	  linkedinContent: string,
510	): Promise<string | null> {
511	  try {
512	    const blogUrl = extractBlogUrl(linkedinContent);
513	    if (!blogUrl) {
514	      console.log(
515	        "No agilepainrelief.com URL found in content, skipping cover image.",
516	      );
517	      return null;
518	    }
519	
520	    console.log(`Fetching cover image from: ${blogUrl}`);
521	
522	    const imageUrl = await fetchCoverImageUrl(blogUrl);
523	    if (!imageUrl) {
524	      return null;
525	    }
526	
527	    console.log(`Cover image URL: ${imageUrl}`);
528	    return imageUrl;
529	  } catch (error) {
530	    console.log(`Warning: Could not fetch cover image: ${error}`);
531	    return null;
532	  }
533	}
534	
535	// ============================================================================
536	// Content Loading
537	// ============================================================================
538	
539	/**
540	 * Check that mastodon.json and bluesky.json are newer than linkedin.txt.
541	 * If either adapted file is older than the source by more than 2 minutes,
542	 * they may be stale (e.g. linkedin.txt was updated but the adaptations
543	 * weren't regenerated). Small differences are tolerated since files may
544	 * be saved moments apart during the same editing session.
545	 */
546	const FRESHNESS_TOLERANCE_MS = 2 * 60 * 1000; // 2 minutes
547	
548	function validateContentFreshness(
549	  linkedinPath: string,
550	  mastodonPath: string,
551	  blueskyPath: string,
552	): string[] {
553	  const linkedinMtime = fs.statSync(linkedinPath).mtimeMs;
554	  const mastodonMtime = fs.statSync(mastodonPath).mtimeMs;
555	  const blueskyMtime = fs.statSync(blueskyPath).mtimeMs;
556	
557	  const staleFiles: string[] = [];
558	  if (linkedinMtime - mastodonMtime > FRESHNESS_TOLERANCE_MS) {
559	    staleFiles.push("mastodon.json");
560	  }
561	  if (linkedinMtime - blueskyMtime > FRESHNESS_TOLERANCE_MS) {
562	    staleFiles.push("bluesky.json");
563	  }
564	  return staleFiles;
565	}
566	
567	function loadPostContent(): PostContent {
568	  const contentDir = path.resolve("social-media", "temp");
569	
570	  const linkedinPath = path.join(contentDir, "linkedin.txt");
571	  const mastodonPath = path.join(contentDir, "mastodon.json");
572	  const blueskyPath = path.join(contentDir, "bluesky.json");
573	
574	  // Verify adapted content is newer than the LinkedIn source
575	  const staleFiles = validateContentFreshness(
576	    linkedinPath,
577	    mastodonPath,
578	    blueskyPath,
579	  );
580	  if (staleFiles.length > 0) {
581	    console.error(
582	      `\nERROR: ${staleFiles.join(" and ")} older than linkedin.txt.`,
583	    );
584	    console.error(
585	      "The adapted content may be stale. Re-run the adapt skill to regenerate.",
586	    );
587	    process.exit(1);
588	  }
589	
590	  const linkedinRaw = fs.readFileSync(linkedinPath, "utf-8").trim();
591	  const mastodonData = JSON.parse(fs.readFileSync(mastodonPath, "utf-8"));
592	  const blueskyData = JSON.parse(fs.readFileSync(blueskyPath, "utf-8"));
593	
594	  // Add UTM parameters to agilepainrelief.com URLs for each platform.
595	  // The LinkedIn link stays inline in the body — no first-comment extraction.
596	  const linkedin = addUtmParamsToText(linkedinRaw, "LinkedIn");
597	  const mastodonWithUtm = addUtmParamsToParts(mastodonData.parts, "Mastodon");
598	  const blueskyWithUtm = addUtmParamsToParts(blueskyData.parts, "Bluesky");
599	
600	  return {
601	    linkedin,
602	    mastodon: mastodonWithUtm,
603	    bluesky: blueskyWithUtm,
604	  };
605	}
606	
607	// ============================================================================
608	// History Management
609	// ============================================================================
610	
611	const HISTORY_PATH = path.resolve("analytics", "history.json");
612	
613	function readHistory(): HistoryData {
614	  const content = fs.readFileSync(HISTORY_PATH, "utf-8");
615	  return JSON.parse(content) as HistoryData;
616	}
617	
618	function writeHistory(data: HistoryData): void {
619	  fs.writeFileSync(HISTORY_PATH, JSON.stringify(data, null, 2) + "\n", "utf-8");
620	}
621	
622	function getNextId(posts: HistoryPost[]): number {
623	  if (posts.length === 0) return 1;
624	  return Math.max(...posts.map((p) => p.id)) + 1;
625	}
626	
627	/**
628	 * Create a new history entry for the scheduled post.
629	 * The posted datetime will be filled in later by the export function.
630	 */
631	function createHistoryEntry(content: PostContent): HistoryPost {
632	  const history = readHistory();
633	  const nextId = getNextId(history.posts);
634	  const createdDate = new Date().toISOString().split("T")[0];
635	
636	  const newPost: HistoryPost = {
637	    id: nextId,
638	    created: createdDate,
639	    posted: "", // Will be updated by export function
640	    linkedin: content.linkedin,
641	    linkedinComment: null, // Links now live inline in the body, not a first comment
642	    mastodon: content.mastodon.length > 0 ? content.mastodon : null,
643	    bluesky:
644	      content.bluesky.length > 0 ? content.bluesky.join("\n\n---\n\n") : null,
645	    topics: [],
646	    links: extractLinks(content.linkedin),
647	    engagement: {},
648	  };
649	
650	  // Add to history and sort by posted date, newest first
651	  history.posts.push(newPost);
652	  history.posts.sort((a, b) => b.posted.localeCompare(a.posted));
653	
654	  writeHistory(history);
655	
656	  console.log(`Created history entry #${nextId} for scheduled post`);
657	  return newPost;
658	}
659	
660	// ============================================================================
661	// Main Execution
662	// ============================================================================
663	
664	async function main() {
665	  const isDryRun = process.argv.includes("--dry-run");
666	  const isShareNow = process.argv.includes("--now");
667	
668	  // Load environment
669	  loadEnv();
670	
671	  console.log("Loading post content...");
672	  const content = loadPostContent();
673	  console.log(`LinkedIn content: ${content.linkedin.length} characters`);
674	  console.log(`Mastodon parts: ${content.mastodon.length}`);
675	  console.log(`Bluesky parts: ${content.bluesky.length}`);
676	
677	  // Validate character limits before attempting to post
678	  const validationErrors = validateCharacterLimits(content);
679	  if (validationErrors.length > 0) {
680	    printValidationErrors(validationErrors);
681	    process.exit(1);
682	  }
683	  console.log("Character limit validation passed.");
684	
685	  // Validate that Mastodon/Bluesky don't mention "link in the comments"
686	  const linkInCommentsErrors = validateNoLinkInComments(content);
687	  if (linkInCommentsErrors.length > 0) {
688	    console.error("\n" + "=".repeat(60));
689	    console.error("CONTENT VALIDATION FAILED");
690	    console.error("=".repeat(60));
691	    for (const err of linkInCommentsErrors) {
692	      console.error(`  ${err}`);
693	    }
694	    console.error(
695	      '\nMastodon and Bluesky don\'t use "link in the comments" — include links inline.',
696	    );
697	    console.error("Please fix the adapted content and try again.");
698	    console.error("=".repeat(60) + "\n");
699	    process.exit(1);
700	  }
701	
702	  // Fetch cover image URL from the blog post linked inline in the LinkedIn body
703	  const coverImageUrl = await fetchCoverImage(content.linkedin);
704	
705	  // Build API inputs for each platform
706	  const mode = isShareNow ? ("shareNow" as const) : ("addToQueue" as const);
707	  const linkedinInput = buildLinkedInInput(content, coverImageUrl, mode);
708	  const mastodonInput = buildMastodonInput(content, coverImageUrl, mode);
709	  const blueskyInput = buildBlueskyInput(content, coverImageUrl, mode);
710	
711	  if (isDryRun) {
712	    console.log("\n" + "=".repeat(60));
713	    console.log("DRY RUN — Not sending to Buffer API");
714	    console.log("=".repeat(60));
715	    console.log("\nLinkedIn payload:");
716	    console.log(JSON.stringify(linkedinInput, null, 2));
717	    console.log("\nMastodon payload:");
718	    console.log(JSON.stringify(mastodonInput, null, 2));
719	    console.log("\nBluesky payload:");
720	    console.log(JSON.stringify(blueskyInput, null, 2));
721	    console.log("\n" + "=".repeat(60));
722	    console.log("Dry run complete. No posts were scheduled.");
723	    console.log("=".repeat(60));
724	    return;
725	  }
726	
727	  console.log("\n" + "=".repeat(60));
728	  console.log(
729	    isShareNow
730	      ? "Publishing posts NOW via Buffer API"
731	      : "Scheduling posts via Buffer API",
732	  );
733	  console.log("=".repeat(60));
734	
735	  // Post to each platform sequentially
736	  for (const [name, input] of [
737	    ["LinkedIn", linkedinInput],
738	    ["Mastodon", mastodonInput],
739	    ["Bluesky", blueskyInput],
740	  ] as [string, CreatePostInput][]) {
741	    console.log(`\nCreating ${name} post...`);
742	
743	    const result = await bufferApiQuery(CREATE_POST_MUTATION, { input });
744	
745	    if (result.errors) {
746	      console.error(`Error creating ${name} post:`);
747	      for (const err of result.errors) {
748	        console.error(`  ${err.message}`);
749	      }
750	      continue;
751	    }
752	
753	    const data = result.data as {
754	      createPost:
755	        | { post: { id: string; text: string; status: string; dueAt: string } }
756	        | { message: string };
757	    };
758	
759	    if ("message" in data.createPost) {
760	      console.error(`${name} post failed: ${data.createPost.message}`);
761	    } else {
762	      const post = data.createPost.post;
763	      console.log(
764	        `${name} post created (id: ${post.id}, status: ${post.status})`,
765	      );
766	    }
767	  }
768	
769	  // Create history entry
770	  createHistoryEntry(content);
771	
772	  console.log(`\n${"=".repeat(60)}`);
773	  console.log("Post scheduling complete!");
774	  console.log(
775	    "History.json has been updated. Posted time will be set by export.",
776	  );
777	  console.log("=".repeat(60));
778	}
779	
780	if (import.meta.url === `file://${process.argv[1]}`) {
781	  main().catch(console.error);
782	}
