import * as fs from "fs";
import * as path from "path";

// ============================================================================
// Types and Interfaces
// ============================================================================

export interface PostContent {
  linkedin: string;
  mastodon: string[];
  bluesky: string[];
}

export type NetworkType = "LinkedIn" | "Mastodon" | "Bluesky";

interface HistoryPost {
  id: number;
  created: string;
  posted: string;
  linkedin: string | null;
  linkedinComment: string | null; // Comment text posted with link
  mastodon: string[] | null;
  bluesky: string | null;
  topics: string[];
  links: string[];
  engagement: Record<string, unknown>;
}

interface HistoryData {
  posts: HistoryPost[];
}

// ============================================================================
// Buffer API Configuration
// ============================================================================

const BUFFER_API_URL = "https://api.buffer.com";

export const CHANNEL_IDS: Record<NetworkType, string> = {
  LinkedIn: "51a55227ead9b8a169000025",
  Mastodon: "6a0b7565090476fb9933fe3a",
  Bluesky: "677c106e4697c1deff913923",
};

// ============================================================================
// Environment Loading
// ============================================================================

export function loadEnv(): void {
  const envPath = path.resolve(".env");
  if (!fs.existsSync(envPath)) {
    console.error(
      "Missing .env file. Create one with BUFFER_API_TOKEN=your_token",
    );
    process.exit(1);
  }

  const content = fs.readFileSync(envPath, "utf-8");
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eqIndex = trimmed.indexOf("=");
    if (eqIndex === -1) continue;
    const key = trimmed.substring(0, eqIndex).trim();
    const value = trimmed.substring(eqIndex + 1).trim();
    if (!process.env[key]) {
      process.env[key] = value;
    }
  }

  if (!process.env.BUFFER_API_TOKEN) {
    console.error("BUFFER_API_TOKEN not set in .env file.");
    process.exit(1);
  }
}

// ============================================================================
// Buffer API Client
// ============================================================================

interface GraphQLResponse<T = unknown> {
  data?: T;
  errors?: Array<{ message: string }>;
}

export const CREATE_POST_MUTATION = `
mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    ... on PostActionSuccess {
      post {
        id
        text
        status
        dueAt
      }
    }
    ... on MutationError {
      message
    }
  }
}`;

export async function bufferApiQuery<T = unknown>(
  query: string,
  variables?: Record<string, unknown>,
): Promise<GraphQLResponse<T>> {
  const token = process.env.BUFFER_API_TOKEN;
  if (!token) throw new Error("BUFFER_API_TOKEN not set");

  const response = await fetch(BUFFER_API_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({ query, variables }),
  });

  if (!response.ok) {
    throw new Error(
      `Buffer API request failed (${response.status}): ${await response.text()}`,
    );
  }

  return (await response.json()) as GraphQLResponse<T>;
}

// ============================================================================
// Post Input Builders
// ============================================================================

export interface CreatePostInput {
  channelId: string;
  text: string;
  schedulingType: "automatic" | "notification";
  mode:
    | "addToQueue"
    | "shareNow"
    | "shareNext"
    | "customScheduled"
    | "recommendedTime";
  dueAt?: string;
  assets?: Array<{ image: { url: string } }>;
  metadata?: {
    mastodon?: {
      thread?: Array<{ text: string }>;
    };
    bluesky?: {
      thread?: Array<{ text: string }>;
    };
  };
}

export function buildLinkedInInput(
  content: PostContent,
  coverImageUrl: string | null,
  mode: CreatePostInput["mode"] = "addToQueue",
): CreatePostInput {
  const input: CreatePostInput = {
    channelId: CHANNEL_IDS.LinkedIn,
    text: content.linkedin,
    schedulingType: "automatic",
    mode,
  };

  if (coverImageUrl) {
    input.assets = [{ image: { url: coverImageUrl } }];
  }

  return input;
}

export function buildMastodonInput(
  content: PostContent,
  coverImageUrl: string | null,
  mode: CreatePostInput["mode"] = "addToQueue",
): CreatePostInput {
  const input: CreatePostInput = {
    channelId: CHANNEL_IDS.Mastodon,
    text: content.mastodon[0],
    schedulingType: "automatic",
    mode,
  };

  if (coverImageUrl) {
    input.assets = [{ image: { url: coverImageUrl } }];
  }

  // Additional parts become thread replies
  if (content.mastodon.length > 1) {
    input.metadata = {
      mastodon: {
        thread: content.mastodon.slice(1).map((text) => ({ text })),
      },
    };
  }

  return input;
}

export function buildBlueskyInput(
  content: PostContent,
  coverImageUrl: string | null,
  mode: CreatePostInput["mode"] = "addToQueue",
): CreatePostInput {
  const input: CreatePostInput = {
    channelId: CHANNEL_IDS.Bluesky,
    text: content.bluesky[0],
    schedulingType: "automatic",
    mode,
  };

  if (coverImageUrl) {
    input.assets = [{ image: { url: coverImageUrl } }];
  }

  // Additional parts become thread replies
  if (content.bluesky.length > 1) {
    input.metadata = {
      bluesky: {
        thread: content.bluesky.slice(1).map((text) => ({ text })),
      },
    };
  }

  return input;
}

// ============================================================================
// Character Limit Validation
// ============================================================================

const CHAR_LIMITS = {
  LinkedIn: 2000,
  Mastodon: 500,
  // Bluesky's hard limit is 300, but we leave a 10-char safety margin —
  // empirically posts at 296-300 chars get rejected.
  Bluesky: 290,
} as const;

// How each network counts a URL toward its character limit.
//  - Mastodon collapses every URL to a fixed 23 chars (its t.co-style rule).
//  - Bluesky and LinkedIn count URLs at FULL length: Buffer no longer shortens
//    links by default (since 2025-04) and Bluesky's API counts the raw URL in
//    the post record, so a long agilepainrelief.com + UTM link eats its whole
//    length. `null` means "count the URL as written".
//  Future: if buff.ly shortening is turned on for a channel (queryable via the
//  API as channel.linkShortening.isEnabled), Bluesky's per-URL count drops to
//  roughly the buff.ly link length (~22). We assume full length until then.
const URL_COUNT_LENGTH: Record<NetworkType, number | null> = {
  LinkedIn: null,
  Mastodon: 23,
  Bluesky: null,
};

// Regex to match URLs (http/https)
const URL_REGEX = /https?:\/\/[^\s]+/g;

export interface ValidationError {
  network: string;
  partIndex: number;
  content: string;
  actualLength: number;
  effectiveLength: number;
  limit: number;
}

/**
 * Effective character count for a network. `urlCount` is the fixed number of
 * characters each URL collapses to on that network, or null to count URLs at
 * their full length (what Bluesky and LinkedIn actually do).
 */
export function calculateEffectiveLength(
  text: string,
  urlCount: number | null,
): number {
  if (urlCount === null) return text.length;
  const urls = text.match(URL_REGEX) || [];
  let effectiveLength = text.length;

  for (const url of urls) {
    // Replace each URL's real length with this network's fixed URL count
    effectiveLength -= url.length;
    effectiveLength += urlCount;
  }

  return effectiveLength;
}

/**
 * Check that Mastodon and Bluesky content does not contain LinkedIn-style
 * "link in the comments" text, since neither platform uses that model.
 */
const LINK_IN_COMMENTS_REGEX = /link(?:s)?\s+in\s+(?:the\s+)?comments/i;

export function validateNoLinkInComments(content: PostContent): string[] {
  const errors: string[] = [];
  for (const [i, part] of content.mastodon.entries()) {
    if (LINK_IN_COMMENTS_REGEX.test(part)) {
      errors.push(`Mastodon part ${i + 1} contains "link in the comments"`);
    }
  }
  for (const [i, part] of content.bluesky.entries()) {
    if (LINK_IN_COMMENTS_REGEX.test(part)) {
      errors.push(`Bluesky part ${i + 1} contains "link in the comments"`);
    }
  }
  return errors;
}

export function validateCharacterLimits(
  content: PostContent,
): ValidationError[] {
  const errors: ValidationError[] = [];

  // Validate LinkedIn (2000 char limit)
  const linkedinLength = content.linkedin.length;
  if (linkedinLength > CHAR_LIMITS.LinkedIn) {
    errors.push({
      network: "LinkedIn",
      partIndex: 1,
      content: content.linkedin,
      actualLength: linkedinLength,
      effectiveLength: linkedinLength,
      limit: CHAR_LIMITS.LinkedIn,
    });
  }

  // Validate Mastodon parts (500 char limit)
  content.mastodon.forEach((part, index) => {
    const effectiveLength = calculateEffectiveLength(
      part,
      URL_COUNT_LENGTH.Mastodon,
    );
    if (effectiveLength > CHAR_LIMITS.Mastodon) {
      errors.push({
        network: "Mastodon",
        partIndex: index + 1,
        content: part,
        actualLength: part.length,
        effectiveLength,
        limit: CHAR_LIMITS.Mastodon,
      });
    }
  });

  // Validate Bluesky parts (300 char limit)
  content.bluesky.forEach((part, index) => {
    const effectiveLength = calculateEffectiveLength(
      part,
      URL_COUNT_LENGTH.Bluesky,
    );
    if (effectiveLength > CHAR_LIMITS.Bluesky) {
      errors.push({
        network: "Bluesky",
        partIndex: index + 1,
        content: part,
        actualLength: part.length,
        effectiveLength,
        limit: CHAR_LIMITS.Bluesky,
      });
    }
  });

  return errors;
}

function printValidationErrors(errors: ValidationError[]): void {
  console.error("\n" + "=".repeat(60));
  console.error("CHARACTER LIMIT VALIDATION FAILED");
  console.error("=".repeat(60));

  for (const error of errors) {
    console.error(
      `\n[${error.network}] Part ${error.partIndex} exceeds ${error.limit} character limit:`,
    );
    console.error(
      `  Effective length: ${error.effectiveLength} characters (after per-network URL counting)`,
    );
    console.error(
      `  Over by: ${error.effectiveLength - error.limit} characters`,
    );
    console.error(`  Content:\n    "${error.content}"`);
  }

  console.error("\n" + "=".repeat(60));
  console.error("Please fix the content and try again.");
  console.error("=".repeat(60) + "\n");
}

// ============================================================================
// LinkedIn Link Extraction
// ============================================================================

/**
 * Extract all URLs from LinkedIn content.
 * Returns an empty array if no URLs are found.
 */
function extractLinks(text: string): string[] {
  return text.match(URL_REGEX) || [];
}

// ============================================================================
// UTM Parameter Handling
// ============================================================================

const AGILEPAINRELIEF_REGEX = /https?:\/\/agilepainrelief\.com[^\s)"]*/gi;
const UTM_PARAMS: Record<NetworkType, string> = {
  LinkedIn: "?utm_source=linkedin&utm_campaign=archive-reshare",
  Mastodon: "?utm_source=mastodon&utm_campaign=archive-reshare",
  Bluesky: "?utm_source=bluesky&utm_campaign=archive-reshare",
};

/**
 * Add UTM parameters to agilepainrelief.com URLs that don't already have utm params.
 * Preserves existing query strings by appending with & instead of ?.
 */
function addUtmToUrl(url: string, utmParams: string): string {
  // Check if URL already has utm parameters
  if (url.includes("utm_")) {
    return url;
  }

  // Check if URL already has query parameters
  if (url.includes("?")) {
    // Append UTM params with & (remove leading ? from utmParams)
    return url + "&" + utmParams.substring(1);
  }

  // No existing query params, add UTM with ?
  return url + utmParams;
}

/**
 * Add UTM parameters to all agilepainrelief.com URLs in text for a specific platform.
 */
export function addUtmParamsToText(
  text: string,
  platform: NetworkType,
): string {
  const utmParams = UTM_PARAMS[platform];
  return text.replace(AGILEPAINRELIEF_REGEX, (url) =>
    addUtmToUrl(url, utmParams),
  );
}

/**
 * Add UTM parameters to all parts of content for a specific platform.
 */
export function addUtmParamsToParts(
  parts: string[],
  platform: NetworkType,
): string[] {
  return parts.map((part) => addUtmParamsToText(part, platform));
}

// ============================================================================
// Cover Image Extraction
// ============================================================================

/**
 * Extract the blog URL from LinkedIn content.
 * Looks for agilepainrelief.com URLs.
 */
function extractBlogUrl(content: string): string | null {
  const match = content.match(AGILEPAINRELIEF_REGEX);
  return match ? match[0] : null;
}

/**
 * Fetch a blog page and extract the og:image URL from its meta tags.
 */
export async function fetchCoverImageUrl(
  blogUrl: string,
): Promise<string | null> {
  const response = await fetch(blogUrl);
  if (!response.ok) {
    console.log(
      `Warning: Failed to fetch blog page (${response.status}): ${blogUrl}`,
    );
    return null;
  }

  const html = await response.text();

  // Match og:image meta tag (handles both attribute orderings)
  const ogImageMatch =
    html.match(
      /<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']*)["']/,
    ) ||
    html.match(
      /<meta[^>]*content=["']([^"']*)["'][^>]*property=["']og:image["']/,
    );

  if (!ogImageMatch) {
    console.log("Warning: No og:image meta tag found on blog page.");
    return null;
  }

  return ogImageMatch[1];
}

/**
 * Extract the cover image URL from the blog post linked in the content.
 * Returns the og:image URL, or null if no image found.
 * Never throws — logs warnings and returns null on failure.
 */
async function fetchCoverImage(
  linkedinContent: string,
): Promise<string | null> {
  try {
    const blogUrl = extractBlogUrl(linkedinContent);
    if (!blogUrl) {
      console.log(
        "No agilepainrelief.com URL found in content, skipping cover image.",
      );
      return null;
    }

    console.log(`Fetching cover image from: ${blogUrl}`);

    const imageUrl = await fetchCoverImageUrl(blogUrl);
    if (!imageUrl) {
      return null;
    }

    console.log(`Cover image URL: ${imageUrl}`);
    return imageUrl;
  } catch (error) {
    console.log(`Warning: Could not fetch cover image: ${error}`);
    return null;
  }
}

// ============================================================================
// Content Loading
// ============================================================================

/**
 * Check that mastodon.json and bluesky.json are newer than linkedin.txt.
 * If either adapted file is older than the source by more than 2 minutes,
 * they may be stale (e.g. linkedin.txt was updated but the adaptations
 * weren't regenerated). Small differences are tolerated since files may
 * be saved moments apart during the same editing session.
 */
const FRESHNESS_TOLERANCE_MS = 2 * 60 * 1000; // 2 minutes

function validateContentFreshness(
  linkedinPath: string,
  mastodonPath: string,
  blueskyPath: string,
): string[] {
  const linkedinMtime = fs.statSync(linkedinPath).mtimeMs;
  const mastodonMtime = fs.statSync(mastodonPath).mtimeMs;
  const blueskyMtime = fs.statSync(blueskyPath).mtimeMs;

  const staleFiles: string[] = [];
  if (linkedinMtime - mastodonMtime > FRESHNESS_TOLERANCE_MS) {
    staleFiles.push("mastodon.json");
  }
  if (linkedinMtime - blueskyMtime > FRESHNESS_TOLERANCE_MS) {
    staleFiles.push("bluesky.json");
  }
  return staleFiles;
}

function loadPostContent(): PostContent {
  const contentDir = path.resolve("social-media", "temp");

  const linkedinPath = path.join(contentDir, "linkedin.txt");
  const mastodonPath = path.join(contentDir, "mastodon.json");
  const blueskyPath = path.join(contentDir, "bluesky.json");

  // Verify adapted content is newer than the LinkedIn source
  const staleFiles = validateContentFreshness(
    linkedinPath,
    mastodonPath,
    blueskyPath,
  );
  if (staleFiles.length > 0) {
    console.error(
      `\nERROR: ${staleFiles.join(" and ")} older than linkedin.txt.`,
    );
    console.error(
      "The adapted content may be stale. Re-run the adapt skill to regenerate.",
    );
    process.exit(1);
  }

  const linkedinRaw = fs.readFileSync(linkedinPath, "utf-8").trim();
  const mastodonData = JSON.parse(fs.readFileSync(mastodonPath, "utf-8"));
  const blueskyData = JSON.parse(fs.readFileSync(blueskyPath, "utf-8"));

  // Add UTM parameters to agilepainrelief.com URLs for each platform.
  // The LinkedIn link stays inline in the body — no first-comment extraction.
  const linkedin = addUtmParamsToText(linkedinRaw, "LinkedIn");
  const mastodonWithUtm = addUtmParamsToParts(mastodonData.parts, "Mastodon");
  const blueskyWithUtm = addUtmParamsToParts(blueskyData.parts, "Bluesky");

  return {
    linkedin,
    mastodon: mastodonWithUtm,
    bluesky: blueskyWithUtm,
  };
}

// ============================================================================
// History Management
// ============================================================================

const HISTORY_PATH = path.resolve("analytics", "history.json");

function readHistory(): HistoryData {
  const content = fs.readFileSync(HISTORY_PATH, "utf-8");
  return JSON.parse(content) as HistoryData;
}

function writeHistory(data: HistoryData): void {
  fs.writeFileSync(HISTORY_PATH, JSON.stringify(data, null, 2) + "\n", "utf-8");
}

function getNextId(posts: HistoryPost[]): number {
  if (posts.length === 0) return 1;
  return Math.max(...posts.map((p) => p.id)) + 1;
}

/**
 * Create a new history entry for the scheduled post.
 * The posted datetime will be filled in later by the export function.
 */
function createHistoryEntry(content: PostContent): HistoryPost {
  const history = readHistory();
  const nextId = getNextId(history.posts);
  const createdDate = new Date().toISOString().split("T")[0];

  const newPost: HistoryPost = {
    id: nextId,
    created: createdDate,
    posted: "", // Will be updated by export function
    linkedin: content.linkedin,
    linkedinComment: null, // Links now live inline in the body, not a first comment
    mastodon: content.mastodon.length > 0 ? content.mastodon : null,
    bluesky:
      content.bluesky.length > 0 ? content.bluesky.join("\n\n---\n\n") : null,
    topics: [],
    links: extractLinks(content.linkedin),
    engagement: {},
  };

  // Add to history and sort by posted date, newest first
  history.posts.push(newPost);
  history.posts.sort((a, b) => b.posted.localeCompare(a.posted));

  writeHistory(history);

  console.log(`Created history entry #${nextId} for scheduled post`);
  return newPost;
}

// ============================================================================
// Main Execution
// ============================================================================

async function main() {
  const isDryRun = process.argv.includes("--dry-run");
  const isShareNow = process.argv.includes("--now");

  // Load environment
  loadEnv();

  console.log("Loading post content...");
  const content = loadPostContent();
  console.log(`LinkedIn content: ${content.linkedin.length} characters`);
  console.log(`Mastodon parts: ${content.mastodon.length}`);
  console.log(`Bluesky parts: ${content.bluesky.length}`);

  // Validate character limits before attempting to post
  const validationErrors = validateCharacterLimits(content);
  if (validationErrors.length > 0) {
    printValidationErrors(validationErrors);
    process.exit(1);
  }
  console.log("Character limit validation passed.");

  // Validate that Mastodon/Bluesky don't mention "link in the comments"
  const linkInCommentsErrors = validateNoLinkInComments(content);
  if (linkInCommentsErrors.length > 0) {
    console.error("\n" + "=".repeat(60));
    console.error("CONTENT VALIDATION FAILED");
    console.error("=".repeat(60));
    for (const err of linkInCommentsErrors) {
      console.error(`  ${err}`);
    }
    console.error(
      '\nMastodon and Bluesky don\'t use "link in the comments" — include links inline.',
    );
    console.error("Please fix the adapted content and try again.");
    console.error("=".repeat(60) + "\n");
    process.exit(1);
  }

  // Fetch cover image URL from the blog post linked inline in the LinkedIn body
  const coverImageUrl = await fetchCoverImage(content.linkedin);

  // Build API inputs for each platform
  const mode = isShareNow ? ("shareNow" as const) : ("addToQueue" as const);
  const linkedinInput = buildLinkedInInput(content, coverImageUrl, mode);
  const mastodonInput = buildMastodonInput(content, coverImageUrl, mode);
  const blueskyInput = buildBlueskyInput(content, coverImageUrl, mode);

  if (isDryRun) {
    console.log("\n" + "=".repeat(60));
    console.log("DRY RUN — Not sending to Buffer API");
    console.log("=".repeat(60));
    console.log("\nLinkedIn payload:");
    console.log(JSON.stringify(linkedinInput, null, 2));
    console.log("\nMastodon payload:");
    console.log(JSON.stringify(mastodonInput, null, 2));
    console.log("\nBluesky payload:");
    console.log(JSON.stringify(blueskyInput, null, 2));
    console.log("\n" + "=".repeat(60));
    console.log("Dry run complete. No posts were scheduled.");
    console.log("=".repeat(60));
    return;
  }

  console.log("\n" + "=".repeat(60));
  console.log(
    isShareNow
      ? "Publishing posts NOW via Buffer API"
      : "Scheduling posts via Buffer API",
  );
  console.log("=".repeat(60));

  // Post to each platform sequentially
  for (const [name, input] of [
    ["LinkedIn", linkedinInput],
    ["Mastodon", mastodonInput],
    ["Bluesky", blueskyInput],
  ] as [string, CreatePostInput][]) {
    console.log(`\nCreating ${name} post...`);

    const result = await bufferApiQuery(CREATE_POST_MUTATION, { input });

    if (result.errors) {
      console.error(`Error creating ${name} post:`);
      for (const err of result.errors) {
        console.error(`  ${err.message}`);
      }
      continue;
    }

    const data = result.data as {
      createPost:
        | { post: { id: string; text: string; status: string; dueAt: string } }
        | { message: string };
    };

    if ("message" in data.createPost) {
      console.error(`${name} post failed: ${data.createPost.message}`);
    } else {
      const post = data.createPost.post;
      console.log(
        `${name} post created (id: ${post.id}, status: ${post.status})`,
      );
    }
  }

  // Create history entry
  createHistoryEntry(content);

  console.log(`\n${"=".repeat(60)}`);
  console.log("Post scheduling complete!");
  console.log(
    "History.json has been updated. Posted time will be set by export.",
  );
  console.log("=".repeat(60));
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch(console.error);
}

