import { describe, it, expect, beforeEach, afterEach } from "vitest";
import * as fs from "fs";
import * as path from "path";
import * as os from "os";
import {
  calculateEffectiveLength,
  validateCharacterLimits,
} from "./bufferPost";

// We need to test the pure builder functions. Since they're not exported from
// bufferPost.ts (which is a script), we duplicate the logic here for testing.
// This mirrors the pattern used in historyStore.test.ts.

// ============================================================================
// Builder functions under test (extracted from bufferPost.ts)
// ============================================================================

const CHANNEL_IDS = {
  LinkedIn: "51a55227ead9b8a169000025",
  Mastodon: "6a0b7565090476fb9933fe3a",
  Bluesky: "677c106e4697c1deff913923",
} as const;

interface PostContent {
  linkedin: string;
  mastodon: string[];
  bluesky: string[];
}

interface CreatePostInput {
  channelId: string;
  text: string;
  schedulingType: "automatic" | "notification";
  mode:
    | "addToQueue"
    | "shareNow"
    | "shareNext"
    | "customScheduled"
    | "recommendedTime";
  dueAt?: string;
  assets?: Array<{ image: { url: string } }>;
  metadata?: {
    mastodon?: {
      thread?: Array<{ text: string }>;
    };
    bluesky?: {
      thread?: Array<{ text: string }>;
    };
  };
}

function buildLinkedInInput(
  content: PostContent,
  coverImageUrl: string | null,
  mode: CreatePostInput["mode"] = "addToQueue",
): CreatePostInput {
  const input: CreatePostInput = {
    channelId: CHANNEL_IDS.LinkedIn,
    text: content.linkedin,
    schedulingType: "automatic",
    mode,
  };
  if (coverImageUrl) {
    input.assets = [{ image: { url: coverImageUrl } }];
  }
  return input;
}

function buildMastodonInput(
  content: PostContent,
  coverImageUrl: string | null,
  mode: CreatePostInput["mode"] = "addToQueue",
): CreatePostInput {
  const input: CreatePostInput = {
    channelId: CHANNEL_IDS.Mastodon,
    text: content.mastodon[0],
    schedulingType: "automatic",
    mode,
  };
  if (coverImageUrl) {
    input.assets = [{ image: { url: coverImageUrl } }];
  }
  if (content.mastodon.length > 1) {
    input.metadata = {
      mastodon: {
        thread: content.mastodon.slice(1).map((text) => ({ text })),
      },
    };
  }
  return input;
}

function buildBlueskyInput(
  content: PostContent,
  coverImageUrl: string | null,
  mode: CreatePostInput["mode"] = "addToQueue",
): CreatePostInput {
  const input: CreatePostInput = {
    channelId: CHANNEL_IDS.Bluesky,
    text: content.bluesky[0],
    schedulingType: "automatic",
    mode,
  };
  if (coverImageUrl) {
    input.assets = [{ image: { url: coverImageUrl } }];
  }
  if (content.bluesky.length > 1) {
    input.metadata = {
      bluesky: {
        thread: content.bluesky.slice(1).map((text) => ({ text })),
      },
    };
  }
  return input;
}

// ============================================================================
// Test Helpers
// ============================================================================

function makeContent(overrides: Partial<PostContent> = {}): PostContent {
  return {
    linkedin:
      "Check out this post https://agilepainrelief.com/blog/some-post",
    mastodon: ["Mastodon part 1"],
    bluesky: ["Bluesky part 1"],
    ...overrides,
  };
}

// ============================================================================
// Tests
// ============================================================================

describe("buildLinkedInInput", () => {
  it("creates basic LinkedIn post input with the link inline in the body", () => {
    const content = makeContent();
    const input = buildLinkedInInput(content, null);

    expect(input.channelId).toBe(CHANNEL_IDS.LinkedIn);
    expect(input.text).toBe(
      "Check out this post https://agilepainrelief.com/blog/some-post",
    );
    expect(input.schedulingType).toBe("automatic");
    expect(input.mode).toBe("addToQueue");
    expect(input.assets).toBeUndefined();
    expect(input.metadata).toBeUndefined();
  });

  it("never sets first-comment metadata (links live in the body)", () => {
    const content = makeContent();
    const input = buildLinkedInInput(content, null);

    expect(input.metadata).toBeUndefined();
  });

  it("includes cover image when provided", () => {
    const content = makeContent();
    const input = buildLinkedInInput(content, "https://example.com/image.jpg");

    expect(input.assets).toEqual([
      { image: { url: "https://example.com/image.jpg" } },
    ]);
  });

  it("omits assets when cover image is null", () => {
    const content = makeContent();
    const input = buildLinkedInInput(content, null);

    expect(input.assets).toBeUndefined();
  });
});

describe("buildMastodonInput", () => {
  it("creates single-part Mastodon post without thread", () => {
    const content = makeContent({ mastodon: ["Only one part"] });
    const input = buildMastodonInput(content, null);

    expect(input.channelId).toBe(CHANNEL_IDS.Mastodon);
    expect(input.text).toBe("Only one part");
    expect(input.schedulingType).toBe("automatic");
    expect(input.mode).toBe("addToQueue");
    expect(input.metadata).toBeUndefined();
  });

  it("creates multi-part Mastodon post with thread", () => {
    const content = makeContent({
      mastodon: ["Part 1", "Part 2", "Part 3"],
    });
    const input = buildMastodonInput(content, null);

    expect(input.text).toBe("Part 1");
    expect(input.metadata).toEqual({
      mastodon: {
        thread: [{ text: "Part 2" }, { text: "Part 3" }],
      },
    });
  });

  it("includes cover image on the main post", () => {
    const content = makeContent({ mastodon: ["Part 1", "Part 2"] });
    const input = buildMastodonInput(content, "https://example.com/cover.png");

    expect(input.assets).toEqual([
      { image: { url: "https://example.com/cover.png" } },
    ]);
  });
});

describe("buildBlueskyInput", () => {
  it("creates single-part Bluesky post without thread", () => {
    const content = makeContent({ bluesky: ["Only one part"] });
    const input = buildBlueskyInput(content, null);

    expect(input.channelId).toBe(CHANNEL_IDS.Bluesky);
    expect(input.text).toBe("Only one part");
    expect(input.schedulingType).toBe("automatic");
    expect(input.mode).toBe("addToQueue");
    expect(input.metadata).toBeUndefined();
  });

  it("creates multi-part Bluesky post with thread", () => {
    const content = makeContent({
      bluesky: ["Part 1", "Part 2", "Part 3"],
    });
    const input = buildBlueskyInput(content, null);

    expect(input.text).toBe("Part 1");
    expect(input.metadata).toEqual({
      bluesky: {
        thread: [{ text: "Part 2" }, { text: "Part 3" }],
      },
    });
  });

  it("includes cover image on the main post", () => {
    const content = makeContent({ bluesky: ["Part 1", "Part 2"] });
    const input = buildBlueskyInput(content, "https://example.com/cover.png");

    expect(input.assets).toEqual([
      { image: { url: "https://example.com/cover.png" } },
    ]);
  });

  it("handles two-part thread correctly", () => {
    const content = makeContent({
      bluesky: ["First", "Second"],
    });
    const input = buildBlueskyInput(content, null);

    expect(input.text).toBe("First");
    expect(input.metadata).toEqual({
      bluesky: {
        thread: [{ text: "Second" }],
      },
    });
  });
});

describe("shareNow mode (--now flag)", () => {
  it("sets LinkedIn mode to shareNow", () => {
    const content = makeContent();
    const input = buildLinkedInInput(content, null, "shareNow");
    expect(input.mode).toBe("shareNow");
  });

  it("sets Mastodon mode to shareNow", () => {
    const content = makeContent({ mastodon: ["Part 1", "Part 2"] });
    const input = buildMastodonInput(content, null, "shareNow");
    expect(input.mode).toBe("shareNow");
  });

  it("sets Bluesky mode to shareNow", () => {
    const content = makeContent({ bluesky: ["Part 1", "Part 2"] });
    const input = buildBlueskyInput(content, null, "shareNow");
    expect(input.mode).toBe("shareNow");
  });

  it("defaults to addToQueue when mode not specified", () => {
    const content = makeContent();
    expect(buildLinkedInInput(content, null).mode).toBe("addToQueue");
    expect(buildMastodonInput(content, null).mode).toBe("addToQueue");
    expect(buildBlueskyInput(content, null).mode).toBe("addToQueue");
  });
});

// ============================================================================
// Link-in-comments validation (extracted from bufferPost.ts)
// ============================================================================

const LINK_IN_COMMENTS_REGEX = /link(?:s)?\s+in\s+(?:the\s+)?comments/i;

function validateNoLinkInComments(content: PostContent): string[] {
  const errors: string[] = [];
  for (const [i, part] of content.mastodon.entries()) {
    if (LINK_IN_COMMENTS_REGEX.test(part)) {
      errors.push(`Mastodon part ${i + 1} contains "link in the comments"`);
    }
  }
  for (const [i, part] of content.bluesky.entries()) {
    if (LINK_IN_COMMENTS_REGEX.test(part)) {
      errors.push(`Bluesky part ${i + 1} contains "link in the comments"`);
    }
  }
  return errors;
}

describe("validateNoLinkInComments", () => {
  it("returns no errors when content is clean", () => {
    const content = makeContent({
      mastodon: ["Check out https://example.com"],
      bluesky: ["Check out https://example.com"],
    });
    expect(validateNoLinkInComments(content)).toEqual([]);
  });

  it("detects 'link in the comments' in Mastodon content", () => {
    const content = makeContent({
      mastodon: ["Check this out (link in the comments)"],
    });
    const errors = validateNoLinkInComments(content);
    expect(errors).toEqual([
      'Mastodon part 1 contains "link in the comments"',
    ]);
  });

  it("detects 'link in the comments' in Bluesky content", () => {
    const content = makeContent({
      bluesky: ["Check this out (link in the comments)"],
    });
    const errors = validateNoLinkInComments(content);
    expect(errors).toEqual([
      'Bluesky part 1 contains "link in the comments"',
    ]);
  });

  it("detects 'links in the comments' (plural)", () => {
    const content = makeContent({
      mastodon: ["See the links in the comments for more"],
    });
    const errors = validateNoLinkInComments(content);
    expect(errors).toHaveLength(1);
  });

