// ============================================================================
// Character limit validation (imported from bufferPost.ts)
// ============================================================================

describe("validateCharacterLimits", () => {
  it("returns no errors when all content is within limits", () => {
    const content = makeContent({
      linkedin: "Short LinkedIn post",
      mastodon: ["Short Mastodon post"],
      bluesky: ["Short Bluesky post"],
    });
    expect(validateCharacterLimits(content)).toEqual([]);
  });

  it("detects LinkedIn content exceeding 2000 characters", () => {
    const longLinkedin = "A".repeat(2001);
    const content = makeContent({
      linkedin: longLinkedin,
      mastodon: ["Short"],
      bluesky: ["Short"],
    });
    const errors = validateCharacterLimits(content);
    expect(errors).toHaveLength(1);
    expect(errors[0].network).toBe("LinkedIn");
    expect(errors[0].actualLength).toBe(2001);
    expect(errors[0].limit).toBe(2000);
  });

  it("allows LinkedIn content at exactly 2000 characters", () => {
    const exactLinkedin = "A".repeat(2000);
    const content = makeContent({
      linkedin: exactLinkedin,
      mastodon: ["Short"],
      bluesky: ["Short"],
    });
    expect(validateCharacterLimits(content)).toEqual([]);
  });

  it("detects Mastodon content exceeding 500 characters", () => {
    const content = makeContent({
      linkedin: "Short",
      mastodon: ["A".repeat(501)],
      bluesky: ["Short"],
    });
    const errors = validateCharacterLimits(content);
    expect(errors).toHaveLength(1);
    expect(errors[0].network).toBe("Mastodon");
    expect(errors[0].limit).toBe(500);
  });

  it("detects Bluesky content exceeding 290 characters", () => {
    const content = makeContent({
      linkedin: "Short",
      mastodon: ["Short"],
      bluesky: ["A".repeat(291)],
    });
    const errors = validateCharacterLimits(content);
    expect(errors).toHaveLength(1);
    expect(errors[0].network).toBe("Bluesky");
    expect(errors[0].limit).toBe(290);
  });

  it("reports errors from multiple platforms", () => {
    const content = makeContent({
      linkedin: "A".repeat(2001),
      mastodon: ["A".repeat(501)],
      bluesky: ["A".repeat(301)],
    });
    const errors = validateCharacterLimits(content);
    expect(errors).toHaveLength(3);
    expect(errors.map((e) => e.network)).toEqual([
      "LinkedIn",
      "Mastodon",
      "Bluesky",
    ]);
  });

  it("uses raw length for LinkedIn (no URL shortening)", () => {
    // LinkedIn with a URL — the full length should count since
    // LinkedIn doesn't get Buffer URL shortening in the same way
    const text = "Check this out " + "https://example.com/very-long-url".padEnd(1234, "x");
    const content = makeContent({
      linkedin: text,
      mastodon: ["Short"],
      bluesky: ["Short"],
    });
    const errors = validateCharacterLimits(content);
    // Should use raw length, not shortened
    if (errors.length > 0) {
      expect(errors[0].actualLength).toBe(text.length);
      expect(errors[0].effectiveLength).toBe(text.length);
    }
  });

  it("counts Mastodon URLs as a fixed 23 characters", () => {
    // 470 body + 120-char URL = 591 raw (over 500), but with the URL collapsed
    // to 23 the effective length is 494, so no error.
    const longUrl = "https://example.com/" + "x".repeat(100);
    const body = "A".repeat(470);
    const content = makeContent({
      linkedin: "Short",
      mastodon: [body + " " + longUrl],
      bluesky: ["Short"],
    });
    expect(validateCharacterLimits(content)).toEqual([]);
  });

  it("counts Bluesky URLs at full length (no shortening)", () => {
    // Body fits under 290 on its own, but the appended full URL pushes the real
    // Bluesky count over 290 - the bug that silently rejected posts.
    const longUrl =
      "https://agilepainrelief.com/some-post/?utm_source=bluesky&utm_campaign=archive-reshare";
    const body = "A".repeat(230);
    const content = makeContent({
      linkedin: "Short",
      mastodon: ["Short"],
      bluesky: [body + "\n\n" + longUrl],
    });
    const errors = validateCharacterLimits(content);
    expect(errors).toHaveLength(1);
    expect(errors[0].network).toBe("Bluesky");
    expect(errors[0].effectiveLength).toBeGreaterThan(290);
  });
});

// ============================================================================
// Content freshness validation (extracted from bufferPost.ts)
// ============================================================================

const FRESHNESS_TOLERANCE_MS = 2 * 60 * 1000; // 2 minutes

function validateContentFreshness(
  linkedinPath: string,
  mastodonPath: string,
  blueskyPath: string,
): string[] {
  const linkedinMtime = fs.statSync(linkedinPath).mtimeMs;
  const mastodonMtime = fs.statSync(mastodonPath).mtimeMs;
  const blueskyMtime = fs.statSync(blueskyPath).mtimeMs;

  const staleFiles: string[] = [];
  if (linkedinMtime - mastodonMtime > FRESHNESS_TOLERANCE_MS) {
    staleFiles.push("mastodon.json");
  }
  if (linkedinMtime - blueskyMtime > FRESHNESS_TOLERANCE_MS) {
    staleFiles.push("bluesky.json");
  }
  return staleFiles;
}

describe("validateContentFreshness", () => {
  let tmpDir: string;
  let linkedinPath: string;
  let mastodonPath: string;
  let blueskyPath: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "freshness-test-"));
    linkedinPath = path.join(tmpDir, "linkedin.txt");
    mastodonPath = path.join(tmpDir, "mastodon.json");
    blueskyPath = path.join(tmpDir, "bluesky.json");
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  it("returns empty array when adapted files are newer than linkedin", () => {
    // Create linkedin first, then adapted files
    fs.writeFileSync(linkedinPath, "old");
    const past = new Date(Date.now() - 2000);
    fs.utimesSync(linkedinPath, past, past);

    fs.writeFileSync(mastodonPath, "{}");
    fs.writeFileSync(blueskyPath, "{}");

    expect(
      validateContentFreshness(linkedinPath, mastodonPath, blueskyPath),
    ).toEqual([]);
  });

  it("returns mastodon.json when it is older than linkedin by more than 2 minutes", () => {
    const now = Date.now();
    const stale = new Date(now - 3 * 60 * 1000); // 3 min ago
    const linkedin = new Date(now);
    const fresh = new Date(now + 1000);

    fs.writeFileSync(mastodonPath, "{}");
    fs.utimesSync(mastodonPath, stale, stale);

    fs.writeFileSync(linkedinPath, "new");
    fs.utimesSync(linkedinPath, linkedin, linkedin);

    fs.writeFileSync(blueskyPath, "{}");
    fs.utimesSync(blueskyPath, fresh, fresh);

    expect(
      validateContentFreshness(linkedinPath, mastodonPath, blueskyPath),
    ).toEqual(["mastodon.json"]);
  });

  it("returns bluesky.json when it is older than linkedin by more than 2 minutes", () => {
    const now = Date.now();
    const stale = new Date(now - 3 * 60 * 1000); // 3 min ago
    const linkedin = new Date(now);
    const fresh = new Date(now + 1000);

    fs.writeFileSync(blueskyPath, "{}");
    fs.utimesSync(blueskyPath, stale, stale);

    fs.writeFileSync(linkedinPath, "new");
    fs.utimesSync(linkedinPath, linkedin, linkedin);

    fs.writeFileSync(mastodonPath, "{}");
    fs.utimesSync(mastodonPath, fresh, fresh);

    expect(
      validateContentFreshness(linkedinPath, mastodonPath, blueskyPath),
    ).toEqual(["bluesky.json"]);
  });

  it("returns both files when both are older than linkedin by more than 2 minutes", () => {
    const now = Date.now();
    const stale = new Date(now - 3 * 60 * 1000); // 3 min ago
    const linkedin = new Date(now);

    fs.writeFileSync(mastodonPath, "{}");
    fs.writeFileSync(blueskyPath, "{}");
    fs.utimesSync(mastodonPath, stale, stale);
    fs.utimesSync(blueskyPath, stale, stale);

    fs.writeFileSync(linkedinPath, "new");
    fs.utimesSync(linkedinPath, linkedin, linkedin);

    expect(
      validateContentFreshness(linkedinPath, mastodonPath, blueskyPath),
    ).toEqual(["mastodon.json", "bluesky.json"]);
  });

  it("tolerates differences within 2 minutes", () => {
    const now = Date.now();
    const withinTolerance = new Date(now - 90 * 1000); // 90 seconds ago
    const linkedin = new Date(now);

    fs.writeFileSync(mastodonPath, "{}");
    fs.writeFileSync(blueskyPath, "{}");
    fs.utimesSync(mastodonPath, withinTolerance, withinTolerance);
    fs.utimesSync(blueskyPath, withinTolerance, withinTolerance);

    fs.writeFileSync(linkedinPath, "new");
    fs.utimesSync(linkedinPath, linkedin, linkedin);

    expect(
      validateContentFreshness(linkedinPath, mastodonPath, blueskyPath),
    ).toEqual([]);
  });

  it("returns empty array when all files have the same mtime", () => {
    fs.writeFileSync(linkedinPath, "content");
    fs.writeFileSync(mastodonPath, "{}");
    fs.writeFileSync(blueskyPath, "{}");
    const now = new Date();
    fs.utimesSync(linkedinPath, now, now);
    fs.utimesSync(mastodonPath, now, now);
    fs.utimesSync(blueskyPath, now, now);

    expect(
      validateContentFreshness(linkedinPath, mastodonPath, blueskyPath),
    ).toEqual([]);
  });
});

