/**
 * One content piece across the three networks.
 *
 * `mastodon`/`bluesky` accept either a single string (one post) or an array of
 * strings (a thread: `parts[0]` is the root, the rest are replies). Threading
 * exists so a network with a tight limit — Bluesky at 290 — can carry the
 * message in the root post and the link in a reply instead of having to
 * condense the message until content + link fit together.
 */
export interface BatchEntry {
  linkedin: string;
  mastodon: string | string[];
  bluesky: string | string[];
  url?: string;
  image?: string;
}

/** Normalize a single-string or multi-part network field to parts. */
function toParts(value: string | string[]): string[] {
  return Array.isArray(value) ? value : [value];
}

