function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim() !== "";
}

/**
 * Shape-check one batch entry. Returns a list of problems (empty when valid).
 */
export function validateBatchEntry(entry: unknown): string[] {
  const problems: string[] = [];
  if (typeof entry !== "object" || entry === null) {
    return ["entry must be an object"];
  }
  const e = entry as Record<string, unknown>;

  if (!isNonEmptyString(e.linkedin)) {
    problems.push("`linkedin` must be a non-empty string");
  }
  for (const field of ["mastodon", "bluesky"] as const) {
    const value = e[field];
    const parts = Array.isArray(value) ? value : [value];
    if (parts.length === 0 || !parts.every(isNonEmptyString)) {
      problems.push(
        `\`${field}\` must be a non-empty string, or an array of non-empty strings (thread parts)`,
      );
    }
  }
  return problems;
}

function readBatchFile(filePath: string): BatchEntry[] {
  if (!fs.existsSync(filePath)) {
    console.error(`Batch file not found: ${filePath}`);
    process.exit(1);
  }
  const raw = fs.readFileSync(filePath, "utf-8");
  const data = JSON.parse(raw);
  if (!Array.isArray(data)) {
    console.error(`Batch file must contain a JSON array, got ${typeof data}`);
    process.exit(1);
  }
  for (const [i, entry] of data.entries()) {
    const problems = validateBatchEntry(entry);
    if (problems.length > 0) {
      console.error(`Entry ${i + 1} is malformed:`);
      for (const problem of problems) console.error(`  • ${problem}`);
      process.exit(1);
    }
  }
  return data;
}

