export function prepareContent(entry: BatchEntry): PreparedEntry {
  const errors: string[] = [];
  const url = entry.url?.trim() || null;

  // Apply UTM to body text first (in case there are inline agilepainrelief.com URLs)
  const linkedinParts = addUtmParamsToParts([entry.linkedin], "LinkedIn");
  const mastodonParts = addUtmParamsToParts(toParts(entry.mastodon), "Mastodon");
  const blueskyParts = addUtmParamsToParts(toParts(entry.bluesky), "Bluesky");

  // Compose final post content. When the `url` field is set and a platform has
  // no inline URL, append the link to that platform's LAST part — the post
  // itself for a single-part entry, the final reply for a thread. The link
  // lives in the body on every platform, LinkedIn included (no first comment).
  function withLink(network: NetworkType, parts: string[]): string[] {
    if (!url) return parts;
    // Conflict check: url field AND an inline URL in any of this platform's parts
    if (parts.some((part) => URL_TEST.test(part))) {
      errors.push(
        `${network} body contains an inline URL AND \`url\` field is set — choose one`,
      );
      return parts;
    }
    const link = addUtmParamsToText(url, network);
    const last = parts.length - 1;
    return parts.map((part, i) => (i === last ? part + "\n\n" + link : part));
  }

  return {
    content: {
      linkedin: withLink("LinkedIn", linkedinParts)[0],
      mastodon: withLink("Mastodon", mastodonParts),
      bluesky: withLink("Bluesky", blueskyParts),
    },
    errors,
  };
}

