import { describe, it, expect } from "vitest";
import { prepareContent, validateBatchEntry, BatchEntry } from "./batchPost";
import { validateCharacterLimits } from "./bufferPost";

function makeEntry(overrides: Partial<BatchEntry> = {}): BatchEntry {
  return {
    linkedin: "LinkedIn body",
    mastodon: "Mastodon body",
    bluesky: "Bluesky body",
    ...overrides,
  };
}

const BLOG_URL = "https://agilepainrelief.com/blog/some-post/";

describe("validateBatchEntry", () => {
  it("accepts single-string networks", () => {
    expect(validateBatchEntry(makeEntry())).toEqual([]);
  });

  it("accepts array (thread) networks", () => {
    const entry = makeEntry({
      mastodon: ["Part 1", "Part 2"],
      bluesky: ["Part 1", "Part 2", "Part 3"],
    });
    expect(validateBatchEntry(entry)).toEqual([]);
  });

  it("accepts a mix of string and array networks", () => {
    expect(validateBatchEntry(makeEntry({ bluesky: ["A", "B"] }))).toEqual([]);
  });

  it("rejects a missing network field", () => {
    const entry = { linkedin: "x", mastodon: "y" };
    expect(validateBatchEntry(entry)).toHaveLength(1);
  });

  it("rejects an empty thread array", () => {
    const problems = validateBatchEntry(makeEntry({ bluesky: [] }));
    expect(problems).toHaveLength(1);
    expect(problems[0]).toContain("bluesky");
  });

  it("rejects a thread with a blank part", () => {
    const problems = validateBatchEntry(
      makeEntry({ mastodon: ["Part 1", "   "] }),
    );
    expect(problems).toHaveLength(1);
    expect(problems[0]).toContain("mastodon");
  });

  it("rejects a thread containing a non-string part", () => {
    const problems = validateBatchEntry(
      makeEntry({ bluesky: ["Part 1", 42] as unknown as string[] }),
    );
    expect(problems).toHaveLength(1);
  });

  it("rejects a blank linkedin body", () => {
    const problems = validateBatchEntry(makeEntry({ linkedin: "" }));
    expect(problems).toHaveLength(1);
    expect(problems[0]).toContain("linkedin");
  });

  it("rejects a non-object entry", () => {
    expect(validateBatchEntry("nope")).toEqual(["entry must be an object"]);
    expect(validateBatchEntry(null)).toEqual(["entry must be an object"]);
  });
});

describe("prepareContent — single-string networks", () => {
  it("wraps each network in a one-part array", () => {
    const { content, errors } = prepareContent(makeEntry());
    expect(errors).toEqual([]);
    expect(content.linkedin).toBe("LinkedIn body");
    expect(content.mastodon).toEqual(["Mastodon body"]);
    expect(content.bluesky).toEqual(["Bluesky body"]);
  });

  it("appends the url field to every network body with per-network UTM", () => {
    const { content, errors } = prepareContent(makeEntry({ url: BLOG_URL }));
    expect(errors).toEqual([]);
    expect(content.linkedin).toBe(
      `LinkedIn body\n\n${BLOG_URL}?utm_source=linkedin&utm_campaign=archive-reshare`,
    );
    expect(content.mastodon).toEqual([
      `Mastodon body\n\n${BLOG_URL}?utm_source=mastodon&utm_campaign=archive-reshare`,
    ]);
    expect(content.bluesky).toEqual([
      `Bluesky body\n\n${BLOG_URL}?utm_source=bluesky&utm_campaign=archive-reshare`,
    ]);
  });

  it("adds UTM to inline agilepainrelief.com URLs", () => {
    const { content } = prepareContent(
      makeEntry({ bluesky: `Read it: ${BLOG_URL}` }),
    );
    expect(content.bluesky).toEqual([
      `Read it: ${BLOG_URL}?utm_source=bluesky&utm_campaign=archive-reshare`,
    ]);
  });
});

describe("prepareContent — threaded networks", () => {
  it("keeps thread parts in order", () => {
    const { content, errors } = prepareContent(
      makeEntry({ bluesky: ["Root", "Reply 1", "Reply 2"] }),
    );
    expect(errors).toEqual([]);
    expect(content.bluesky).toEqual(["Root", "Reply 1", "Reply 2"]);
  });

  it("appends the url to the LAST part, not the root", () => {
    const { content, errors } = prepareContent(
      makeEntry({ bluesky: ["Root", "Reply"], url: BLOG_URL }),
    );
    expect(errors).toEqual([]);
    expect(content.bluesky).toEqual([
      "Root",
      `Reply\n\n${BLOG_URL}?utm_source=bluesky&utm_campaign=archive-reshare`,
    ]);
  });

  it("threads Mastodon the same way", () => {
    const { content } = prepareContent(
      makeEntry({ mastodon: ["Root", "Reply"], url: BLOG_URL }),
    );
    expect(content.mastodon).toEqual([
      "Root",
      `Reply\n\n${BLOG_URL}?utm_source=mastodon&utm_campaign=archive-reshare`,
    ]);
  });

  it("lets one network thread while the others stay single-part", () => {
    const { content } = prepareContent(
      makeEntry({ bluesky: ["Root", "Reply"], url: BLOG_URL }),
    );
    expect(content.mastodon).toHaveLength(1);
    expect(content.bluesky).toHaveLength(2);
    expect(content.linkedin).toContain("utm_source=linkedin");
  });

  it("lets a link-only reply carry a Bluesky post that would otherwise overflow", () => {
    // 280-char message + a UTM'd link is well over Bluesky's 290 budget in one
    // post, but fits when the link moves to a reply.
    const message = "A".repeat(280);
    const single = prepareContent(
      makeEntry({ bluesky: message, url: BLOG_URL }),
    );
    expect(validateCharacterLimits(single.content)).not.toEqual([]);

    const threaded = prepareContent(
      makeEntry({ bluesky: [message, "Full post:"], url: BLOG_URL }),
    );
    expect(validateCharacterLimits(threaded.content)).toEqual([]);
  });

  it("still flags an over-limit reply part", () => {
    const { content } = prepareContent(
      makeEntry({ bluesky: ["Root", "B".repeat(291)] }),
    );
    const errors = validateCharacterLimits(content);
    expect(errors).toHaveLength(1);
    expect(errors[0].network).toBe("Bluesky");
    expect(errors[0].partIndex).toBe(2);
  });
});

describe("prepareContent — inline URL vs url field conflict", () => {
  it("flags a conflict when the single-part body already has a URL", () => {
    const { errors } = prepareContent(
      makeEntry({ bluesky: `Read ${BLOG_URL}`, url: BLOG_URL }),
    );
    expect(errors).toEqual([
      "Bluesky body contains an inline URL AND `url` field is set — choose one",
    ]);
  });

  it("flags a conflict when any thread part has a URL", () => {
    const { errors, content } = prepareContent(
      makeEntry({ bluesky: ["Root", `Read ${BLOG_URL}`], url: BLOG_URL }),
    );
    expect(errors).toEqual([
      "Bluesky body contains an inline URL AND `url` field is set — choose one",
    ]);
    // On conflict the link is not appended — the entry fails pre-flight instead.
    expect(content.bluesky[1]).not.toContain("\n\n");
  });

  it("flags a conflict on a non-final thread part too", () => {
    const { errors } = prepareContent(
      makeEntry({ mastodon: [`Read ${BLOG_URL}`, "Reply"], url: BLOG_URL }),
    );
    expect(errors).toHaveLength(1);
    expect(errors[0]).toContain("Mastodon");
  });

  it("reports a conflict per network", () => {
    const { errors } = prepareContent(
      makeEntry({
        linkedin: `Read ${BLOG_URL}`,
        mastodon: ["Root", `Read ${BLOG_URL}`],
        bluesky: "Clean body",
        url: BLOG_URL,
      }),
    );
    expect(errors).toHaveLength(2);
    expect(errors[0]).toContain("LinkedIn");
    expect(errors[1]).toContain("Mastodon");
  });

  it("allows inline URLs when no url field is set", () => {
    const { errors } = prepareContent(
      makeEntry({ bluesky: ["Root", `Read ${BLOG_URL}`] }),
    );
    expect(errors).toEqual([]);
  });
});

